{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "A glucose conjugate of ketoprofen was directly measured to cross the BBB in rat brain perfusion (1.33 pmol/mg/min), demonstrating that attaching a sugar to a lipophilic drug does not preclude CNS access and can involve transporter-mediated uptake; this is highly transferable to the query's glucose-bearing diterpenoid structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Liquiritin, a glucoside natural product, was detected in rat brain after systemic administration, providing direct evidence that glycosylated molecules can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Abiraterone, a tetracyclic terpenoid/steroid, achieved brain concentrations 5-9 times higher than blood, supporting CNS access for the query's rigid lipophilic diterpene core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "α-Turmerone, a lipophilic sesquiterpenoid, was detected in mouse brain after systemic exposure, supporting that terpenoid natural products can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental analogues, including glucose conjugates, glycosides, and tetracyclic terpenoids, demonstrate meaningful CNS access after systemic administration. The query's glucose-bearing diterpenoid structure aligns with these directly measured permeable phenotypes, overriding the uncertain physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement for the exact query molecule.",
    "The aldehyde group's metabolic reactivity and possible efflux liability were not directly tested.",
    "Quantitative brain-to-plasma exposure for the query is not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

